select a.id, a.code, a.name, a.area_id, a.reservoir_id, a.status, a.remark, a.create_by, a.create_time, tr.name as reservoirName, ta.name as areaName from t_good_shelf a left join t_reservoir tr on tr.id = a.reservoir_id left join t_area ta on ta.id = a.area_id
inner join sys_user u on u.user_name = a.create_by and u.status = '0' inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'
a.del_flag = '0' and a.code like concat('%', #{code}, '%') and a.name like concat('%', #{name}, '%') and a.area_id = #{areaId} and a.reservoir_id = #{reservoirId} and a.status = #{status}
